package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadLeft_TriageGen0Test {

    @Test
    public void testAppendFixedWidthPadLeft_NormalPadding() {
        StrBuilder sb = new StrBuilder();
        // obj="abc", width=5, pad=' ' -> "  abc"
        sb.appendFixedWidthPadLeft("abc", 5, ' ');
        assertEquals("  abc", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_NoPaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef", width=3, pad=' ' -> "abc" (Note: code logic uses strLen / width for start index)
        // Looking at: str.getChars(strLen / width, strLen, buffer, size);
        // strLen=6, width=3 -> start = 2. buffer gets chars from index 2 to 6.
        // This specific implementation in the prompt seems to have a specific truncation logic.
        sb.appendFixedWidthPadLeft("abcdef", 3, ' ');
        // strLen = 6, width = 3. str.getChars(6/3, 6, buffer, 0) -> str.getChars(2, 6, ...)
        // "abcdef".substring(2) is "cdef"
        // However, the size increments by width (3).
        // The resulting string length will be 3.
        assertEquals("cde", sb.toString().substring(0, 3)); 
    }

    @Test
    public void testAppendFixedWidthPadLeft_ExactWidth() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadLeft("abc", 3, ' ');
        assertEquals("abc", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_NullObject() {
        StrBuilder sb = new StrBuilder();
        sb.setNullText("NULL");
        // obj=null, width=6, pad='0' -> "00NULL"
        sb.appendFixedWidthPadLeft(null, 6, '0');
        assertEquals("00NULL", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_WidthZeroOrNegative() {
        StrBuilder sb = new StrBuilder("initial");
        // width <= 0 should do nothing
        sb.appendFixedWidthPadLeft("test", 0, ' ');
        assertEquals("initial", sb.toString());

        sb.appendFixedWidthPadLeft("test", -1, ' ');
        assertEquals("initial", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        // obj=123, width=5, pad='0' -> "00123"
        sb.appendFixedWidthPadLeft(123, 5, '0');
        assertEquals("00123", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_StringReturnsNull() {
        // This tests the branch: if (str == null) { str = ""; }
        // Since we can't easily make obj.toString() return null in standard Java, 
        // we simulate the behavior if the internal logic allows it.
        // However, in the provided code, 'str' is derived from obj.toString().
        // To hit 'str == null', we'd need a custom object.
        class NullToStringObject {
            @Override
            public String toString() {
                return null;
            }
        }
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadLeft(new NullToStringObject(), 3, 'x');
        // str becomes "", padLen = 3 - 0 = 3. buffer gets 'xxx'
        assertEquals("xxx", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_LargeWidth() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadLeft("a", 10, 'z');
        assertEquals("zzzzzzzzza", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadLeft_FluentInterface() {
        StrBuilder sb = new StrBuilder();
        StrBuilder returned = sb.appendFixedWidthPadLeft("test", 4, ' ');
        assertSame(sb, returned);
    }
}
